// Flatten calendar events into one reminder task per attendee per due window.
// Windows are 2h wide and the workflow runs hourly, so every event is caught
// exactly once per window. The Sheets log downstream guarantees zero duplicates
// even if you re-run manually.
//   24h reminder -> event starts 23-25 hours from now
//    2h reminder -> event starts 1-3 hours from now
const now = Date.now();
const HOUR = 3600 * 1000;
const out = [];

for (const item of $input.all()) {
  const ev = item.json;

  // Skip cancelled events and events without a concrete start time
  if (ev.status === 'cancelled') continue;
  const startRaw = ev.start && (ev.start.dateTime || ev.start.date);
  if (!startRaw) continue;
  const start = new Date(startRaw).getTime();
  if (isNaN(start)) continue;

  const hoursUntil = (start - now) / HOUR;
  let reminderType = null;
  if (hoursUntil >= 23 && hoursUntil < 25) reminderType = '24h';
  else if (hoursUntil >= 1 && hoursUntil < 3) reminderType = '2h';
  if (!reminderType) continue;

  // Only remind real guests: skip the organizer, yourself, meeting rooms,
  // and anyone who already declined.
  const attendees = (ev.attendees || []).filter(function (a) {
    return a.email && !a.organizer && !a.self && !a.resource && a.responseStatus !== 'declined';
  });
  if (attendees.length === 0) continue;

  const startDate = new Date(startRaw);
  const readable = startDate.toLocaleString('en-US', {
    weekday: 'long', month: 'long', day: 'numeric',
    hour: 'numeric', minute: '2-digit'
  });

  for (const a of attendees) {
    out.push({
      json: {
        dedupe_key: ev.id + '|' + a.email + '|' + reminderType,
        event_id: ev.id,
        event_title: ev.summary || 'Your appointment',
        event_description: (ev.description || '').replace(/<[^>]*>/g, ' ').slice(0, 400),
        event_location: ev.location || '',
        meeting_link: ev.hangoutLink || '',
        event_start_iso: startRaw,
        event_start_readable: readable,
        event_timezone: (ev.start && ev.start.timeZone) || '',
        attendee_email: a.email,
        attendee_name: a.displayName || a.email.split('@')[0],
        organizer_name: (ev.organizer && (ev.organizer.displayName || ev.organizer.email)) || 'the team',
        reminder_type: reminderType,
        hours_until: Math.round(hoursUntil * 10) / 10
      }
    });
  }
}

return out;

// Duplicate protection: drop any reminder whose dedupe_key already exists
// in the ReminderLog sheet. dedupe_key = eventId|attendeeEmail|reminderType,
// so each guest gets at most one 24h email and one 2h email per event -
// even across manual re-runs, restarts, or overlapping executions.
const queue = $('Build Reminder Queue').all();
const logRows = $input.all();

const alreadySent = new Set();
for (const row of logRows) {
  const key = row.json && row.json.dedupe_key;
  if (key) alreadySent.add(String(key).trim());
}

const fresh = queue.filter(function (item) {
  return !alreadySent.has(item.json.dedupe_key);
});

return fresh;

// Safely parse the AI's JSON output. If the model ever returns malformed JSON
// (or the API errors), we fall back to a clean built-in template so the
// reminder ALWAYS goes out - a bad AI response never costs you a show-up.
const reminder = $('Loop Over Reminders').first().json;

let subject = '';
let bodyHtml = '';

try {
  const raw = $input.first().json;
  let content = '';
  if (raw.choices && raw.choices[0] && raw.choices[0].message) {
    content = raw.choices[0].message.content || '';
  }
  // Strip accidental markdown fences before parsing
  content = content.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const parsed = JSON.parse(content);
  if (parsed.subject && parsed.body_html) {
    subject = String(parsed.subject).slice(0, 200);
    bodyHtml = String(parsed.body_html);
  }
} catch (e) {
  // fall through to the template below
}

if (!subject || !bodyHtml) {
  const linkLine = reminder.meeting_link
    ? '<p><a href="' + reminder.meeting_link + '">Join your meeting here</a></p>'
    : (reminder.event_location ? '<p>Location: ' + reminder.event_location + '</p>' : '');
  subject = (reminder.reminder_type === '2h' ? 'Starting soon: ' : 'Reminder: ')
    + reminder.event_title + ' - ' + reminder.event_start_readable;
  bodyHtml = '<p>Hi ' + reminder.attendee_name + ',</p>'
    + '<p>This is a friendly reminder about <strong>' + reminder.event_title + '</strong> on '
    + reminder.event_start_readable + '.</p>'
    + linkLine
    + '<p>Need to reschedule? Just reply to this email.</p>'
    + '<p>See you soon,<br>' + reminder.organizer_name + '</p>';
}

return [{
  json: Object.assign({}, reminder, {
    email_subject: subject,
    email_body: bodyHtml,
    sent_at: new Date().toISOString()
  })
}];
